$env=array_replace(getenv(),['FMONITOR_DB_NAME'=>'runtime_contract','FMONITOR_DB_USER'=>'runtime','FMONITOR_DB_PASSWORD'=>'private','FMONITOR_MIGRATION_DB_PASSWORD'=>'private-admin','FMONITOR_MIGRATION_DB_USER'=>'root','FMONITOR_PROCESS_TABLE_PREFIX'=>'fm_','FMONITOR_LEGACY_TABLE_PREFIX'=>'fm_','FMONITOR_SESSION_INSTANCE'=>'contract','FMONITOR_TRUSTED_REQUEST_HOST'=>'localhost','FMONITOR_TRUSTED_REQUEST_SCHEME'=>'http','FMONITOR_RUNTIME_IMAGE'=>'registry.invalid/fmonitor2@sha256:'.str_repeat('1',64)]);
function jrcRun(array$args,array$env,string$cwd):array{$p=[];$r=proc_open($args,[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$p,$cwd,$env);if(!is_resource($r))throw new TestFailure('SETUP_FAILURE process');foreach($p as$q)stream_set_blocking($q,false);$o='';$e='';$deadline=microtime(true)+10;$exit=null;do{$o.=stream_get_contents($p[1]);$e.=stream_get_contents($p[2]);$s=proc_get_status($r);if(!$s['running']){$exit=$s['exitcode'];break;}if(microtime(true)>=$deadline){proc_terminate($r,9);throw new TestFailure('SETUP_FAILURE command timeout');}usleep(10000);}while(true);$o.=stream_get_contents($p[1]);$e.=stream_get_contents($p[2]);foreach($p as$q)fclose($q);$closed=proc_close($r);return[$exit!==null&&$exit>=0?$exit:$closed,$o,$e];}
$env['FMONITOR_YII_COOKIE_VALIDATION_KEY']='jobs-contract-test-cookie-validation-key';
$env['FMONITOR_YII_IDENTITY_KEY']='jobs-contract-test-identity-key';
[$exit,$default,$error]=jrcRun(['docker','compose','-f','deploy/runtime/compose.yaml','config','--services'],$env,$root);assertSameValue([0,''],[$exit,$error],'default compose resolves');assertSameValue(['db','migrate','php','web'],array_values(array_filter(explode("\n",trim($default)))),'default topology includes required migration and excludes opt-in jobs');
[$exit,$json,$error]=jrcRun(['docker','compose','-f','deploy/runtime/compose.yaml','--profile','jobs','config','--format','json'],$env,$root);assertSameValue([0,''],[$exit,$error],'jobs compose resolves');$model=json_decode($json,true,512,JSON_THROW_ON_ERROR);foreach(['jobs-worker'=>'worker','jobs-scheduler'=>'scheduler']as$name=>$mode){$service=$model['services'][$name]??null;assertSameValue(true,is_array($service),'jobs profile contains '.$name);assertSameValue(['jobs'],$service['profiles'],'jobs service has exact opt-in profile');assertSameValue(false,array_key_exists('ports',$service),'jobs service has no ports');assertSameValue($model['services']['php']['image'],$service['image'],'jobs service uses exact php image');assertSameValue(['php','bin/yii','jobs/'.$mode,'--interactive=0'],$service['command'],'jobs service exact Yii2 CLI role');assertSameValue('service_completed_successfully',$service['depends_on']['migrate']['condition']??null,'jobs wait for canonical migration');assertSameValue(['SIGTERM',true],[$service['stop_signal'],in_array($service['stop_grace_period'],['60s','1m0s'],true)],'jobs service exact 60-second graceful stop contract');assertSameValue(false,(bool)preg_match('/migrate|bootstrap|docker-bootstrap|php\s+-S|socat/i',implode(' ',$service['command'])),'jobs command has no startup migration/demo');if($mode==='worker'){foreach(['/run/fmonitor-secrets/bitrix-token','/run/fmonitor-secrets/bitrix-ca.pem']as$target){$mount=array_values(array_filter($service['volumes']??[],static fn(array$v):bool=>($v['target']??null)===$target));assertSameValue([1,true],[count($mount),(bool)($mount[0]['read_only']??false)],'worker private mount is explicit read-only '.$target);}}else{$encoded=json_encode([$service['environment']??[],$service['volumes']??[]],JSON_THROW_ON_ERROR);assertSameValue(false,str_contains($encoded,'BITRIX'),'scheduler receives no Bitrix configuration');assertSameValue(false,str_contains($encoded,'bitrix-'),'scheduler receives no transport secret mount');}}
$source=file_get_contents($jobs).file_get_contents($handler);assertSameValue(false,(bool)preg_match('/FMONITOR_DEMO_|PILOT_ACTIVE_MANIFEST|docker-bootstrap|fmonitor2-migrate|CREATE\s+TABLE|ALTER\s+TABLE|php\s+-S|socat/i',$source),'Jobs CLI has no demo/bootstrap/migration/DDL proxy');echo "PASS: JOBS-RUNTIME-WIRING-001 resolved Compose boundary\n";
